def snappy_decompress(src):
    out=bytearray(); i=0
    # varint uncompressed length
    shift=0; length=0
    while True:
        b=src[i]; i+=1; length|=(b&0x7f)<<shift
        if not b&0x80: break
        shift+=7
    while i<len(src):
        tag=src[i]; i+=1; typ=tag&3
        if typ==0:
            l=tag>>2
            if l<60: n=l+1
            else:
                nb=l-59; n=int.from_bytes(src[i:i+nb],'little')+1; i+=nb
            out.extend(src[i:i+n]); i+=n
        elif typ==1:
            n=((tag>>2)&7)+4; off=((tag&0xe0)<<3)|src[i]; i+=1
            for _ in range(n): out.append(out[-off])
        elif typ==2:
            n=(tag>>2)+1; off=src[i]|(src[i+1]<<8); i+=2
            for _ in range(n): out.append(out[-off])
        else:
            n=(tag>>2)+1; off=int.from_bytes(src[i:i+4],'little'); i+=4
            for _ in range(n): out.append(out[-off])
    # if len(out)!=length: print('snappy len mismatch', len(out), length, file=sys.stderr)
    return bytes(out)

def bit_width(x): return 0 if x<=0 else x.bit_length()
def read_var(buf, pos):
    shift=0; res=0
    while True:
        b=buf[pos]; pos+=1; res|=(b&0x7f)<<shift
        if not b&0x80: return res,pos
        shift+=7

def unpack_bits(buf,pos,count,width):
    vals=[]; bitpos=pos*8
    for _ in range(count):
        v=0
        for b in range(width):
            if buf[bitpos//8] & (1<<(bitpos%8)): v|=1<<b
            bitpos+=1
        vals.append(v)
    return vals,(bitpos+7)//8

def read_hybrid(buf,pos,count,width,with_length=False):
    end=None
    if with_length:
        L=struct.unpack('<I',buf[pos:pos+4])[0]; pos+=4; end=pos+L
    vals=[]
    if width==0: return [0]*count,pos
    while len(vals)<count and pos<len(buf):
        header,pos=read_var(buf,pos)
        if header&1:
            groups=header>>1; n=groups*8
            vv,pos=unpack_bits(buf,pos,n,width); vals.extend(vv[:max(0,count-len(vals))])
        else:
            run=header>>1; nbytes=(width+7)//8; v=int.from_bytes(buf[pos:pos+nbytes],'little'); pos+=nbytes; vals.extend([v]*min(run,count-len(vals)))
    return vals,pos

def plain_decode(buf, ptype, count, type_len=None):
    vals=[]; pos=0
    for _ in range(count):
        if ptype==0:
            # bool bit-packed LSB
            bit_index=len(vals); byte=buf[bit_index//8]; vals.append(bool(byte & (1<<(bit_index%8))))
            pos=(len(vals)+7)//8
        elif ptype==1: vals.append(struct.unpack('<i',buf[pos:pos+4])[0]); pos+=4
        elif ptype==2: vals.append(struct.unpack('<q',buf[pos:pos+8])[0]); pos+=8
        elif ptype==3: vals.append(buf[pos:pos+12]); pos+=12
        elif ptype==4: vals.append(struct.unpack('<f',buf[pos:pos+4])[0]); pos+=4
        elif ptype==5: vals.append(struct.unpack('<d',buf[pos:pos+8])[0]); pos+=8
        elif ptype==6:
            n=struct.unpack('<I',buf[pos:pos+4])[0]; pos+=4; vals.append(buf[pos:pos+n]); pos+=n
        elif ptype==7:
            n=type_len or 0; vals.append(buf[pos:pos+n]); pos+=n
    return vals,pos

def codec_decompress(codec, payload, unc_size):
    if codec==0: return payload
    if codec==1: return snappy_decompress(payload)
    if codec==2: return zlib.decompress(payload, 16+zlib.MAX_WBITS)
    return payload

def build_tree(schema):
    idx=0; leaves=[]; leaf_elems=[]
    def rec(depth,path):
        nonlocal idx
        me=schema[idx]; idx+=1; name=me.get(4,b'').decode('utf8','replace')
        n=me.get(5,0) or 0
        if n:
            for _ in range(n): rec(depth+1,path+[name])
        else:
            leaves.append(path+[name]); leaf_elems.append(me)
    if schema: rec(0,[])
    return leaves,leaf_elems

def max_levels(schema, leaf_path):
    # traverse schema list pre-order matching path after root
    maxdef=maxrep=0; stack=[]; idx=0
    res=[]
    def rec(path, repdefs):
        nonlocal idx,res
        me=schema[idx]; idx+=1; name=me.get(4,b'').decode('utf8','replace'); n=me.get(5,0) or 0
        rt=me.get(3)
        md,mr=repdefs
        if idx!=1: # non-root
            if rt==1: md+=1
            elif rt==2: md+=1; mr+=1
        if n:
            for _ in range(n): rec(path+[name], (md,mr))
        else:
            res.append((path+[name], md, mr, me))
    if schema: rec([], (0,0))
    for path,md,mr,me in res:
        if path[1:] == leaf_path or path == leaf_path: return md,mr
    return 0,0

