        return self._values_cache

# ---- value decoding ----
def bit_width(x): return 0 if x<=0 else int(x).bit_length()
def read_var(buf,pos):
    shift=0; res=0
    while pos < len(buf):
        b=buf[pos]; pos+=1; res |= (b&0x7f)<<shift
        if not b&0x80: return res,pos
        shift += 7
    return res,pos

def unpack_bits(buf,pos,count,width):
    vals=[]; bitpos=pos*8
    if width==0: return [0]*count, pos
    for _ in range(count):
        v=0
        for b in range(width):
            if bitpos//8 < len(buf) and (buf[bitpos//8] & (1<<(bitpos%8))): v |= 1<<b
            bitpos += 1
        vals.append(v)
    return vals, (bitpos+7)//8

def read_hybrid(buf,pos,count,width,with_length=False, limit=None):
    if width==0: return [0]*count, pos
    end = len(buf) if limit is None else min(len(buf), limit)
    if with_length:
        if pos+4 > len(buf): return [],pos
        L=struct.unpack('<I', buf[pos:pos+4])[0]; pos += 4; end=min(len(buf), pos+L)
    vals=[]
    while len(vals)<count and pos<end:
        header,pos = read_var(buf,pos)
        if header & 1:
            groups=header>>1; n=groups*8
            vv,pos=unpack_bits(buf,pos,n,width)
            vals.extend(vv[:count-len(vals)])
        else:
            run=header>>1; nb=(width+7)//8
            v=int.from_bytes(buf[pos:pos+nb], 'little') if nb else 0; pos += nb
            vals.extend([v]*min(run,count-len(vals)))
    if len(vals)<count: vals.extend([0]*(count-len(vals)))
    return vals,pos

def plain_decode(buf, ptype, count, type_len=None):
    vals=[]; pos=0
    for i in range(count):
        if ptype==0:
            vals.append(bool(buf[i//8] & (1<<(i%8))) if i//8 < len(buf) else False); pos=(i+8)//8
        elif ptype==1:
            if pos+4>len(buf): break
            vals.append(struct.unpack('<i',buf[pos:pos+4])[0]); pos+=4
        elif ptype==2:
            if pos+8>len(buf): break
            vals.append(struct.unpack('<q',buf[pos:pos+8])[0]); pos+=8
        elif ptype==3:
            if pos+12>len(buf): break
            vals.append(buf[pos:pos+12]); pos+=12
        elif ptype==4:
            if pos+4>len(buf): break
            vals.append(struct.unpack('<f',buf[pos:pos+4])[0]); pos+=4
        elif ptype==5:
            if pos+8>len(buf): break
            vals.append(struct.unpack('<d',buf[pos:pos+8])[0]); pos+=8
        elif ptype==6:
            if pos+4>len(buf): break
            n=struct.unpack('<I',buf[pos:pos+4])[0]; pos+=4
            vals.append(buf[pos:pos+n]); pos+=n
        elif ptype==7:
            n=type_len or 0; vals.append(buf[pos:pos+n]); pos+=n
    return vals,pos

def delta_binary_decode(buf, count):
    pos=0
    try:
        block,pos=read_var(buf,pos); mini,pos=read_var(buf,pos); total,pos=read_var(buf,pos); first,pos=read_var(buf,pos)
        first=(first>>1)^-(first&1)
        total=min(count,total)
        vals=[first]
        mb_size=max(1, block//max(1,mini))
        while len(vals)<total and pos<len(buf):
            mind,pos=read_var(buf,pos); mind=(mind>>1)^-(mind&1)
            widths=list(buf[pos:pos+mini]); pos+=mini
            for w in widths:
                n=min(mb_size, total-len(vals))
                packed,pos=unpack_bits(buf,pos,n,w)
                for x in packed[:n]: vals.append(vals[-1]+mind+x)
                if len(vals)>=total: break
        return vals[:count],pos
    except Exception:
        return [],pos

def decode_indices(buf, pos, count):
    if count<=0: return [],pos
    if pos>=len(buf): return [0]*count,pos
    bw=buf[pos]; pos+=1
    vals,pos=read_hybrid(buf,pos,count,bw,with_length=False)
    return vals,pos

def decode_column(pq, colchunk):
    md=colchunk.get(3,{})
    ptype=md.get(1); codec=md.get(4,0); path=[bs(x) for x in md.get(3,[]) or []]
    maxdef,maxrep,se=pq.max_levels_for_path(path)
    type_len=se.get(2)
    dict_vals=None; vals=[]; defs=[]; reps=[]
    pos=md.get(11) or md.get(9) or colchunk.get(2,0) or 0
    want=int(md.get(5,0) or 0)
    safety=0
    while pos < len(pq.data) and (len(defs) if maxdef or maxrep else len(vals)) < want and safety < 10000:
        safety += 1
        p=CompactProto(pq.data,pos)
        h=p.read_struct(); hs=p.i-pos
        if 1 not in h or 3 not in h: break
        payload=pq.data[pos+hs:pos+hs+int(h.get(3,0) or 0)]
        pos += hs + int(h.get(3,0) or 0)
        typ=h.get(1)
        if typ==2:
            dh=h.get(7,{})
            dbuf=decompress(codec,payload,h.get(2))
            n=int(dh.get(1,0) or 0)
            enc=dh.get(2,0)
            # Dictionary pages are normally plain or plain-dictionary.
            dict_vals,_=plain_decode(dbuf,ptype,n,type_len)
        elif typ==0:
            dh=h.get(5,{})
            n=int(dh.get(1,0) or 0)
            buf=decompress(codec,payload,h.get(2))
            bpos=0
            if maxrep:
                rr,bpos=read_hybrid(buf,bpos,n,bit_width(maxrep),with_length=True); reps.extend(rr)
            else: rr=[0]*n
            if maxdef:
                dd,bpos=read_hybrid(buf,bpos,n,bit_width(maxdef),with_length=True); defs.extend(dd)
            else:
                dd=[maxdef]*n
            nonnull=sum(1 for d in dd if d==maxdef)
            enc=dh.get(2,0)
            page_vals=[]
            if enc in (2,8):
                idxs,bpos=decode_indices(buf,bpos,nonnull)
                page_vals=[dict_vals[i] if dict_vals is not None and 0<=i<len(dict_vals) else i for i in idxs]
            elif enc==0:
                page_vals,_=plain_decode(buf[bpos:],ptype,nonnull,type_len)
            elif enc==3 and ptype==0:
                page_vals,_=read_hybrid(buf,bpos,nonnull,1,with_length=True)
                page_vals=[bool(x) for x in page_vals]
            elif enc==5:
                page_vals,_=delta_binary_decode(buf[bpos:],nonnull)
            it=iter(page_vals)
            for d in dd:
                vals.append(next(it,None) if d==maxdef else None)
        elif typ==3:
            dh=h.get(8,{})
            n=int(dh.get(1,0) or 0); num_nulls=int(dh.get(2,0) or 0)
            rep_len=int(dh.get(5,0) or 0); def_len=int(dh.get(6,0) or 0)
            bpos=0
            if maxrep:
                rr,_=read_hybrid(payload,0,n,bit_width(maxrep),with_length=False,limit=rep_len); reps.extend(rr)
            else: rr=[0]*n
            bpos += rep_len
            if maxdef:
                dd,_=read_hybrid(payload,bpos,n,bit_width(maxdef),with_length=False,limit=bpos+def_len); defs.extend(dd)
            else: dd=[maxdef]*n
            bpos += def_len
            vcomp=payload[bpos:]
            value_unc=max(0, int(h.get(2,0) or 0)-rep_len-def_len)
            if codec and dh.get(7, True) is not False:
                vbuf=decompress(codec,vcomp,value_unc or None)
            else: vbuf=vcomp
            nonnull=sum(1 for d in dd if d==maxdef)
            enc=dh.get(4,0)
            page_vals=[]
            if enc in (2,8):
                idxs,_=decode_indices(vbuf,0,nonnull)
                page_vals=[dict_vals[i] if dict_vals is not None and 0<=i<len(dict_vals) else i for i in idxs]
            elif enc==0:
                page_vals,_=plain_decode(vbuf,ptype,nonnull,type_len)
            elif enc==3 and ptype==0:
                page_vals,_=read_hybrid(vbuf,0,nonnull,1,with_length=True)
                page_vals=[bool(x) for x in page_vals]
            elif enc==5:
                page_vals,_=delta_binary_decode(vbuf,nonnull)
            it=iter(page_vals)
            for d in dd:
                vals.append(next(it,None) if d==maxdef else None)
        else:
            break
    return vals, defs, reps, maxdef, maxrep, se

def is_utf8_schema(se):
    # ConvertedType UTF8 = 0, LogicalType STRING uses field 1 in the union.
    return se.get(6)==0 or (isinstance(se.get(10),dict) and 1 in se.get(10,{}))

def int96_to_dt(b):
    if not isinstance(b,(bytes,bytearray)) or len(b)!=12: return None
    ns=struct.unpack('<Q', b[:8])[0]; jd=struct.unpack('<I', b[8:])[0]
    # Julian day to Gregorian date
    l=jd+68569; n=4*l//146097; l=l-(146097*n+3)//4; i=4000*(l+1)//1461001
    l=l-1461*i//4+31; j=80*l//2447; day=l-2447*j//80; l=j//11; month=j+2-12*l; year=100*(n-49)+i+l
    secs=ns//1000000000
    try:
        return datetime.datetime(year,month,day) + datetime.timedelta(seconds=secs, microseconds=(ns%1000000000)//1000)
    except Exception: return None

def format_scalar(v, se=None, in_list=False):
    if v is None: return 'null' if in_list else 'NULL'
    ptype=se.get(1) if se else None
    if ptype==3:
        dt=int96_to_dt(v)
        if dt: return dt.strftime('%Y-%m-%d %H:%M:%S')
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,float):
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return 'inf' if v>0 else '-inf'
        s=("%.7g" % v) if ptype==4 else ("%.15g" % v)
        if 'e' not in s and 'E' not in s and '.' not in s: s += '.0'
        return s
    if isinstance(v,int): return str(v)
    if isinstance(v,(bytes,bytearray)):
        if is_utf8_schema(se):
            txt=v.decode('utf-8','replace')
            return '"%s"' % txt.replace('"','\\"')
        try: txt=v.decode('utf-8')
        except Exception: txt=None
        if txt is not None and all((32 <= ord(c) < 127) for c in txt):
            return 'b"%s"' % txt.replace('"','\\"')
        return 'b"' + bytes(v).hex() + '"'
    if isinstance(v,list):
        parts=[format_scalar(x,se,True) for x in v]
        if len(parts)>3: parts=[parts[0], '…', parts[-1]]
        return '[' + ', '.join(parts) + ']'
    if isinstance(v,dict):
        items=[]
        for k,val in list(v.items())[:4]: items.append(str(k)+': '+format_scalar(val,None,True))
        return '{' + ', '.join(items) + '}'
    return str(v)

def group_repeated(vals, defs, reps, maxdef, maxrep, rows):
    out=[]; cur=[]; row_started=False; vi=0
    for i,d in enumerate(defs):
        r=reps[i] if i<len(reps) else 0
        if r==0:
            if row_started: out.append(cur)
            cur=[]; row_started=True
        if d==0 and not cur:
            cur=None
        elif cur is not None:
            if d==maxdef: cur.append(vals[i] if i<len(vals) else None)
            elif d>=max(1,maxdef-1): cur.append(None)
            else:
                # empty/null list marker; keep as empty unless already null
                pass
    if row_started: out.append(cur)
    while len(out)<rows: out.append(None)
    return out[:rows]

def decode_rows(pq):
    rows=[{} for _ in range(pq.num_rows)]
    if not pq.row_groups: return rows
    row_base=0
    # use first N rows per group; enough for TUI browsing and usually complete for samples
    for rg in pq.row_groups:
        group_rows=int(rg.get(3,0) or 0)
        bytop=defaultdict(dict)
        for c in rg.get(1,[]) or []:
            md=c.get(3,{})
            path=[bs(x) for x in md.get(3,[]) or []]
            if not path: continue
            vals,defs,reps,maxdef,maxrep,se=decode_column(pq,c)
            colvals = group_repeated(vals,defs,reps,maxdef,maxrep,group_rows) if maxrep else vals[:group_rows]
            top=path[0]
            rest=path[1:]
            if rest:
                bytop[top][tuple(rest)] = (colvals,se)
            else:
                for i,v in enumerate(colvals):
                    if row_base+i < len(rows): rows[row_base+i][top]=(v,se)
        # turn simple list leaves into top-level values; structs become dicts
        for top,parts in bytop.items():
            if len(parts)==1:
                (rest,(colvals,se)), = parts.items()
                for i,v in enumerate(colvals):
                    if row_base+i < len(rows): rows[row_base+i][top]=(v,se)
            else:
                for i in range(group_rows):
                    d={}
                    for rest,(colvals,se) in parts.items():
                        if i < len(colvals): d['.'.join(rest)] = colvals[i]
                    if row_base+i < len(rows): rows[row_base+i][top]=(d,{})
        row_base += group_rows
    return rows

# ---- rendering helpers ----
def term_size():
    try:
        s=shutil.get_terminal_size((100,30)); return max(20,s.columns), max(10,s.lines)
    except Exception: return 100,30

def strip_ansi_len(s): return len(s)
def trunc(s,n):
    if n<=0: return ''
    return s if len(s)<=n else s[:max(0,n-1)]+'…'
def pad(s,n):
    s=trunc(s,n); return s + ' '*(max(0,n-len(s)))
def human(n):
    n=int(n or 0)
    if abs(n) < 1024: return f"{n} B"
    for unit in ['KiB','MiB','GiB']:
        n2=n/1024.0
        if abs(n2)<1024: return f"{n2:.1f} {unit}"
        n=n2
    return f"{n:.1f} TiB"
def ratio(raw,comp): return "0.00x" if not comp else f"{raw/comp:.2f}x"

def border_line(w,left='╭',mid='─',right='╮'): return left + mid*(w-2) + right

def header_lines(pq, active, w):
    tabs=['Visualize','Metadata','Schema','Row Groups']
    tabstr='  ' + '   '.join(tabs)
    path=pq.path
    inner=w-2
    avail=inner-len(tabstr)
    p=trunc(path, max(0,avail-1))
    spaces=max(1, inner-len(tabstr)-len(p))
    return [border_line(w), '│' + pad(tabstr + ' '*spaces + p, inner) + '│', border_line(w,'╰','─','╯')]

def footer(tab,w):
    if tab==0:
        txt='parqeye                               ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit'
    elif tab==2:
        txt='parqeye                                          ←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit'
    elif tab==3:
        txt='parqeye                              →/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit'
    else:
        txt='parqeye                                                                       [Tab] Next Tab, [Q]uit'
    return pad(txt,w)

class App:
    def __init__(self,pq):
        self.pq=pq; self.tab=0; self.row=0; self.col=0; self.schema_scroll=0; self.rg=0
    def draw(self):
        w,h=term_size(); lines=[]; lines += header_lines(self.pq,self.tab,w)
        if self.tab==0: lines += self.draw_visual(w,h)
        elif self.tab==1: lines += self.draw_metadata(w,h)
        elif self.tab==2: lines += self.draw_schema(w,h, row_groups=False)
        else: lines += self.draw_rowgroups(w,h)
        # ensure exactly h lines including footer
        body=lines[:h-1]
        while len(body)<h-1: body.append(' '*w)
        body.append(footer(self.tab,w))
        sys.stdout.write('\x1b[1;1H' + '\n'.join(pad(x,w) for x in body[:h]) + '\x1b[?25l')
        sys.stdout.flush()
    def draw_visual(self,w,h):
        try: rows=self.pq.values()
        except RuntimeError as e: raise
        cols=self.pq.top_columns
        # compute display matrix for visible rows
        values=[]
        for r in rows:
            values.append([format_scalar(*(r.get(c,(None,{})))) for c in cols])
        widths=[]
        for j,c in enumerate(cols):
            mx=len(c)
            for i in range(min(len(values), max(20,h))):
                if j < len(values[i]): mx=max(mx,len(values[i][j]))
            widths.append(max(10,mx+2))
        # horizontal offset by selected column, but show as many as fit
        start=min(self.col, max(0,len(cols)-1))
        # keep selected in view; original scrolls one column at a time
        rem=w-9; visible=[]; used=0
        for j in range(start,len(cols)):
            if used + widths[j] > rem and visible: break
            visible.append(j); used += widths[j]
        header=' '*9
        for j in visible: header += pad(cols[j], widths[j])
        out=[pad(header,w), '──────┬' + '─'*(max(0,w-7))]
        visible_rows=max(0,h-6); row_start=max(0, min(self.row, max(0,len(rows)-1)))
        # keep selected row at top like ratatui table after page-down? for arrows keep simple
        if row_start and row_start+visible_rows>len(rows): row_start=max(0,len(rows)-visible_rows)
        for line_no in range(visible_rows):
            i=row_start+line_no
            if i < len(rows):
                s=f"{i+1:<6}│  "
                for j in visible:
                    val=values[i][j] if j<len(values[i]) else 'NULL'
                    s += pad(val, widths[j])
                out.append(pad(s,w))
            else:
                out.append('      │')
        return out
    def draw_metadata(self,w,h):
        raw,comp,cols,codecs,encs=self.pq.size_stats()
        codec_s=', '.join(f"{k}({v})" for k,v in sorted(codecs.items())) if codecs else ''
        order=[0,2,3,4,5,6,7,8,9]
        enc_s=', '.join(ENC.get(e,str(e)) for e in order if e in encs)
        fields=[('Format version', str(self.pq.meta.get(1,''))),('Created by', self.pq.created_by),('Rows', str(self.pq.num_rows)),('Columns', str(cols)),('Row groups', str(len(self.pq.row_groups))),('Size (raw)', human(raw)),('Size (compressed)', human(comp)),('Compression ratio', ratio(raw,comp)),('Codecs (cols)', codec_s),('Encodings', enc_s),('Avg row size', human(raw//self.pq.num_rows if self.pq.num_rows else 0))]
        labelw=max(len(k) for k,v in fields)
        content=[(' '*max(0,labelw-len(k)) + k + ' ' + v) for k,v in fields]
        bw=min(w, max(30, max(len(x) for x in content)+4))
        left=max(0,(w-bw)//2); top=max(0,(h-3-len(content)-2)//2)
        out=[' '*w for _ in range(top)]
        title='File Metadata'; dash=bw-2-len(title); l=dash//2; r=dash-l
        out.append(' '*left + '╭' + '─'*l + title + '─'*r + '╮')
        for c in content:
            out.append(' '*left + '│ ' + pad(c,bw-4) + ' │')
        out.append(' '*left + '╰' + '─'*(bw-2) + '╯')
        return out
    def schema_tree_lines(self): return [x[0] for x in self.pq.lines]
    def col_stat_map(self):
        mp={}
        if not self.pq.row_groups: return mp
        totals={}
        for rg in self.pq.row_groups:
            for c in rg.get(1,[]) or []:
                md=c.get(3,{})
                path='.'.join(bs(x) for x in md.get(3,[]) or [])
                a=totals.setdefault(path,[md.get(1),md.get(4),0,0])
                a[2]+=int(md.get(7,0) or 0); a[3]+=int(md.get(6,0) or 0)
        return totals
    def draw_schema(self,w,h,row_groups=False):
        tree=self.schema_tree_lines(); max_tree=max([len(x) for x in tree]+[11])
        left_w=min(max(23,max_tree+4), max(20,w//3))
        right_w=max(10,w-left_w)
        title='Schema Tree'; dash=left_w-2-len(title); topL='╭'+'─'*(dash//2)+title+'─'*(dash-dash//2)+'╮'
        title2='Column Statistics'; dash2=right_w-2-len(title2); topR='╭'+'─'*(dash2//2)+title2+'─'*(dash2-dash2//2)+'╮'
        out=[topL+topR]
        stat=self.col_stat_map(); leaf_iter=iter([])
        # map schema line path to leaf stats
        line_stats=[]
        for line,se,path in self.pq.lines:
            p='.'.join(path[1:] if path and path[0] in ('schema','spark_schema','root') else path)
            if se.get(5,0): line_stats.append((RT.get(se.get(3),''), 'group', '', '', ''))
            else:
                # match suffix too
                key=p; a=stat.get(key)
                if a is None:
                    for k,v in stat.items():
                        if k.endswith(key): a=v; break
                comp=human(a[2]) if a else ''; unc=human(a[3]) if a else ''; rat=ratio(a[3],a[2]) if a and a[2] else ''
                line_stats.append((RT.get(se.get(3),''), PT.get(se.get(1),'group'), comp, unc, rat))
        visible=h-5
        for i in range(visible):
            idx=i+self.schema_scroll
            ltxt=tree[idx] if idx<len(tree) else ''
            if idx < len(line_stats):
                rep,phys,comp,unc,rat=line_stats[idx]
                if i==0:
                    rtxt='Repetition  Physical    Compressed  Uncompressed  Ratio'
                else:
                    rtxt=f"{rep:<12}{phys:<12}{comp:<12}{unc:<14}{rat}"
            else: rtxt=''
            out.append('│'+pad(ltxt,left_w-2)+'│'+'│'+pad(rtxt,right_w-2)+'│')
        legend='Leaf, Group'; dash=left_w-2-len(legend); botL='╰'+'─'*(dash//2)+legend+'─'*(dash-dash//2)+'╯'
        botR='╰'+'─'*(right_w-2)+'╯'
        out.append(botL+botR)
        return out
    def draw_rowgroups(self,w,h):
        # Similar to original: schema tree at left and row-group summary at right.
        tree=self.schema_tree_lines(); max_tree=max([len(x) for x in tree]+[11])
        left_w=min(max(22,max_tree+3), max(20,w//4))
        rw=w-left_w
        out=[]
        title='Schema Tree'; dash=left_w-2-len(title); topL='╭'+'─'*(dash//2)+title+'─'*(dash-dash//2)+'╮'
        rg_count=max(1,len(self.pq.row_groups)); idx=min(self.rg,rg_count-1)
        titleR=f" Row Group: {idx+1} / {rg_count} "; topR='┌'+titleR+'─'*(max(0,rw-2-len(titleR)))+'┐'
        out.append(topL+topR)
        rows_total=sum(int(rg.get(3,0) or 0) for rg in self.pq.row_groups) or self.pq.num_rows
        raw,comp,cols,codecs,encs=self.pq.size_stats()
        rg=self.pq.row_groups[idx] if self.pq.row_groups else {}
        rg_raw=sum(int(c.get(3,{}).get(6,0) or 0) for c in rg.get(1,[]) or [])
        rg_comp=sum(int(c.get(3,{}).get(7,0) or 0) for c in rg.get(1,[]) or [])
        bar='█'*max(0,rw-2)
