    return vals, defs, reps, maxdef, maxrep, se

def is_utf8_schema(se):
    # ConvertedType UTF8 = 0, LogicalType STRING uses field 1 in the union.
    return se.get(6)==0 or (isinstance(se.get(10),dict) and 1 in se.get(10,{}))

def int96_to_dt(b):
    if not isinstance(b,(bytes,bytearray)) or len(b)!=12: return None
    ns=struct.unpack('<Q', b[:8])[0]; jd=struct.unpack('<I', b[8:])[0]
    # Julian day to Gregorian date
    l=jd+68569; n=4*l//146097; l=l-(146097*n+3)//4; i=4000*(l+1)//1461001
    l=l-1461*i//4+31; j=80*l//2447; day=l-2447*j//80; l=j//11; month=j+2-12*l; year=100*(n-49)+i+l
    secs=ns//1000000000
    try:
        return datetime.datetime(year,month,day) + datetime.timedelta(seconds=secs, microseconds=(ns%1000000000)//1000)
    except Exception: return None

def format_scalar(v, se=None, in_list=False):
    if v is None: return 'null' if in_list else 'NULL'
    ptype=se.get(1) if se else None
    if ptype==3:
        dt=int96_to_dt(v)
        if dt: return dt.strftime('%Y-%m-%d %H:%M:%S')
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,float):
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return 'inf' if v>0 else '-inf'
        s=("%.7g" % v) if ptype==4 else ("%.15g" % v)
        if 'e' not in s and 'E' not in s and '.' not in s: s += '.0'
        return s
    if isinstance(v,int): return str(v)
    if isinstance(v,(bytes,bytearray)):
        if is_utf8_schema(se):
            txt=v.decode('utf-8','replace')
            return '"%s"' % txt.replace('"','\\"')
        try: txt=v.decode('utf-8')
        except Exception: txt=None
        if txt is not None and all((32 <= ord(c) < 127) for c in txt):
            return 'b"%s"' % txt.replace('"','\\"')
        return 'b"' + bytes(v).hex() + '"'
    if isinstance(v,list):
        parts=[format_scalar(x,se,True) for x in v]
        if len(parts)>3: parts=[parts[0], '…', parts[-1]]
        return '[' + ', '.join(parts) + ']'
    if isinstance(v,dict):
        items=[]
        for k,val in list(v.items())[:4]: items.append(str(k)+': '+format_scalar(val,None,True))
        return '{' + ', '.join(items) + '}'
    return str(v)

def group_repeated(vals, defs, reps, maxdef, maxrep, rows):
    out=[]; cur=[]; row_started=False; vi=0
    for i,d in enumerate(defs):
        r=reps[i] if i<len(reps) else 0
        if r==0:
            if row_started: out.append(cur)
            cur=[]; row_started=True
        if d==0 and not cur:
            cur=None
        elif cur is not None:
            if d==maxdef: cur.append(vals[i] if i<len(vals) else None)
            elif d>=max(1,maxdef-1): cur.append(None)
            else:
                # empty/null list marker; keep as empty unless already null
                pass
    if row_started: out.append(cur)
    while len(out)<rows: out.append(None)
    return out[:rows]

def decode_rows(pq):
    rows=[{} for _ in range(pq.num_rows)]
    if not pq.row_groups: return rows
    row_base=0
    # use first N rows per group; enough for TUI browsing and usually complete for samples
    for rg in pq.row_groups:
        group_rows=int(rg.get(3,0) or 0)
        bytop=defaultdict(dict)
        for c in rg.get(1,[]) or []:
            md=c.get(3,{})
            path=[bs(x) for x in md.get(3,[]) or []]
            if not path: continue
            vals,defs,reps,maxdef,maxrep,se=decode_column(pq,c)
            colvals = group_repeated(vals,defs,reps,maxdef,maxrep,group_rows) if maxrep else vals[:group_rows]
            top=path[0]
            rest=path[1:]
            if rest:
                bytop[top][tuple(rest)] = (colvals,se)
            else:
                for i,v in enumerate(colvals):
                    if row_base+i < len(rows): rows[row_base+i][top]=(v,se)
        # turn simple list leaves into top-level values; structs become dicts
        for top,parts in bytop.items():
            if len(parts)==1:
                (rest,(colvals,se)), = parts.items()
                for i,v in enumerate(colvals):
                    if row_base+i < len(rows): rows[row_base+i][top]=(v,se)
            else:
                for i in range(group_rows):
                    d={}
                    for rest,(colvals,se) in parts.items():
                        if i < len(colvals): d['.'.join(rest)] = colvals[i]
                    if row_base+i < len(rows): rows[row_base+i][top]=(d,{})
        row_base += group_rows
    return rows

# ---- rendering helpers ----
def term_size():
    try:
        s=shutil.get_terminal_size((100,30)); return max(20,s.columns), max(10,s.lines)
    except Exception: return 100,30

def strip_ansi_len(s): return len(s)
def trunc(s,n):
    if n<=0: return ''
    return s if len(s)<=n else s[:max(0,n-1)]+'…'
def pad(s,n):
    s=trunc(s,n); return s + ' '*(max(0,n-len(s)))
def human(n):
    n=int(n or 0)
    if abs(n) < 1024: return f"{n} B"
    for unit in ['KiB','MiB','GiB']:
        n2=n/1024.0
        if abs(n2)<1024: return f"{n2:.1f} {unit}"
        n=n2
    return f"{n:.1f} TiB"
def ratio(raw,comp): return "0.00x" if not comp else f"{raw/comp:.2f}x"

def border_line(w,left='╭',mid='─',right='╮'): return left + mid*(w-2) + right

def header_lines(pq, active, w):
    tabs=['Visualize','Metadata','Schema','Row Groups']
    tabstr='  ' + '   '.join(tabs)
    path=pq.path
    inner=w-2
    avail=inner-len(tabstr)
    p=trunc(path, max(0,avail-1))
    spaces=max(1, inner-len(tabstr)-len(p))
    return [border_line(w), '│' + pad(tabstr + ' '*spaces + p, inner) + '│', border_line(w,'╰','─','╯')]

def footer(tab,w):
    if tab==0:
        txt='parqeye                               ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit'
    elif tab==2:
        txt='parqeye                                          ←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit'
    elif tab==3:
        txt='parqeye                              →/← : Iterate Row Groups, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit'
    else:
        txt='parqeye                                                                       [Tab] Next Tab, [Q]uit'
    return pad(txt,w)

class App:
    def __init__(self,pq):
        self.pq=pq; self.tab=0; self.row=0; self.col=0; self.schema_scroll=0; self.rg=0
    def draw(self):
        w,h=term_size(); lines=[]; lines += header_lines(self.pq,self.tab,w)
        if self.tab==0: lines += self.draw_visual(w,h)
        elif self.tab==1: lines += self.draw_metadata(w,h)
        elif self.tab==2: lines += self.draw_schema(w,h, row_groups=False)
        else: lines += self.draw_rowgroups(w,h)
        # ensure exactly h lines including footer
        body=lines[:h-1]
        while len(body)<h-1: body.append(' '*w)
        body.append(footer(self.tab,w))
        sys.stdout.write('\x1b[1;1H' + '\n'.join(pad(x,w) for x in body[:h]) + '\x1b[?25l')
        sys.stdout.flush()
    def draw_visual(self,w,h):
        try: rows=self.pq.values()
        except RuntimeError as e: raise
        cols=self.pq.top_columns
        # compute display matrix for visible rows
        values=[]
        for r in rows:
            values.append([format_scalar(*(r.get(c,(None,{})))) for c in cols])
        widths=[]
        for j,c in enumerate(cols):
            mx=len(c)
            for i in range(min(len(values), max(20,h))):
                if j < len(values[i]): mx=max(mx,len(values[i][j]))
            widths.append(max(10,mx+2))
        # horizontal offset by selected column, but show as many as fit
        start=min(self.col, max(0,len(cols)-1))
        # keep selected in view; original scrolls one column at a time
        rem=w-9; visible=[]; used=0
        for j in range(start,len(cols)):
            if used + widths[j] > rem and visible: break
            visible.append(j); used += widths[j]
        header=' '*9
        for j in visible: header += pad(cols[j], widths[j])
        out=[pad(header,w), '──────┬' + '─'*(max(0,w-7))]
        visible_rows=max(0,h-6); row_start=max(0, min(self.row, max(0,len(rows)-1)))
        # keep selected row at top like ratatui table after page-down? for arrows keep simple
        if row_start and row_start+visible_rows>len(rows): row_start=max(0,len(rows)-visible_rows)
        for line_no in range(visible_rows):
            i=row_start+line_no
            if i < len(rows):
                s=f"{i+1:<6}│  "
                for j in visible:
                    val=values[i][j] if j<len(values[i]) else 'NULL'
                    s += pad(val, widths[j])
                out.append(pad(s,w))
            else:
                out.append('      │')
        return out
    def draw_metadata(self,w,h):
        raw,comp,cols,codecs,encs=self.pq.size_stats()
        codec_s=', '.join(f"{k}({v})" for k,v in sorted(codecs.items())) if codecs else ''
        order=[0,2,3,4,5,6,7,8,9]
        enc_s=', '.join(ENC.get(e,str(e)) for e in order if e in encs)
        fields=[('Format version', str(self.pq.meta.get(1,''))),('Created by', self.pq.created_by),('Rows', str(self.pq.num_rows)),('Columns', str(cols)),('Row groups', str(len(self.pq.row_groups))),('Size (raw)', human(raw)),('Size (compressed)', human(comp)),('Compression ratio', ratio(raw,comp)),('Codecs (cols)', codec_s),('Encodings', enc_s),('Avg row size', human(raw//self.pq.num_rows if self.pq.num_rows else 0))]
        labelw=max(len(k) for k,v in fields)
        content=[(' '*max(0,labelw-len(k)) + k + ' ' + v) for k,v in fields]
        bw=min(w, max(30, max(len(x) for x in content)+4))
        left=max(0,(w-bw)//2); top=max(0,(h-3-len(content)-2)//2)
        out=[' '*w for _ in range(top)]
        title='File Metadata'; dash=bw-2-len(title); l=dash//2; r=dash-l
        out.append(' '*left + '╭' + '─'*l + title + '─'*r + '╮')
        for c in content:
            out.append(' '*left + '│ ' + pad(c,bw-4) + ' │')
        out.append(' '*left + '╰' + '─'*(bw-2) + '╯')
        return out
    def schema_tree_lines(self): return [x[0] for x in self.pq.lines]
    def col_stat_map(self):
        mp={}
        if not self.pq.row_groups: return mp
        totals={}
        for rg in self.pq.row_groups:
            for c in rg.get(1,[]) or []:
                md=c.get(3,{})
                path='.'.join(bs(x) for x in md.get(3,[]) or [])
                a=totals.setdefault(path,[md.get(1),md.get(4),0,0])
                a[2]+=int(md.get(7,0) or 0); a[3]+=int(md.get(6,0) or 0)
