    def draw_schema(self,w,h,row_groups=False):
        tree=self.schema_tree_lines(); max_tree=max([len(x) for x in tree]+[11])
        left_w=min(max(23,max_tree+4), max(20,w//3))
        right_w=max(10,w-left_w)
        title='Schema Tree'; dash=left_w-2-len(title); topL='╭'+'─'*(dash//2)+title+'─'*(dash-dash//2)+'╮'
        title2='Column Statistics'; dash2=right_w-2-len(title2); topR='╭'+'─'*(dash2//2)+title2+'─'*(dash2-dash2//2)+'╮'
        out=[topL+topR]
        stat=self.col_stat_map(); leaf_iter=iter([])
        # map schema line path to leaf stats
        line_stats=[]
        for line,se,path in self.pq.lines:
            p='.'.join(path[1:] if path and path[0] in ('schema','spark_schema','root') else path)
            if se.get(5,0): line_stats.append((RT.get(se.get(3),''), 'group', '', '', ''))
            else:
                # match suffix too
                key=p; a=stat.get(key)
                if a is None:
