                        if k.endswith(key): a=v; break
                comp=human(a[2]) if a else ''; unc=human(a[3]) if a else ''; rat=ratio(a[3],a[2]) if a and a[2] else ''
                line_stats.append((RT.get(se.get(3),''), PT.get(se.get(1),'group'), comp, unc, rat))
        visible=h-5
        for i in range(visible):
            idx=i+self.schema_scroll
