        tree=self.schema_tree_lines(); max_tree=max([len(x) for x in tree]+[11])
        left_w=min(max(22,max_tree+3), max(20,w//4))
        rw=w-left_w
        out=[]
        title='Schema Tree'; dash=left_w-2-len(title); topL='╭'+'─'*(dash//2)+title+'─'*(dash-dash//2)+'╮'
