            elif i==4: rtxt=f"Uncompressed: {human(rg_raw)} / {human(raw)}    Ratio: {ratio(rg_raw,rg_comp)}"
            elif i==6: rtxt='    Compressed vs Uncompressed (B)'
            elif i==8: rtxt='                •'
