        legend='Leaf, Group'; dash=left_w-2-len(legend); out.append('╰'+'─'*(dash//2)+legend+'─'*(dash-dash//2)+'╯'+'Row Group')
        return out
    def handle(self, key):
        if key in ('q','Q','\x03'): return False
        if key=='\t': self.tab=(self.tab+1)%4
        elif key in ('\x1b[Z',): self.tab=(self.tab-1)%4
        elif key in ('\x1b[C','l'):
            if self.tab==0: self.col=min(self.col+1,max(0,len(self.pq.top_columns)-1))
            elif self.tab==3: self.rg=min(self.rg+1,max(0,len(self.pq.row_groups)-1))
        elif key in ('\x1b[D','h'):
            if self.tab==0: self.col=max(0,self.col-1)
            elif self.tab==3: self.rg=max(0,self.rg-1)
        elif key in ('\x1b[B','j'):
            if self.tab==0: self.row=min(self.row+1,max(0,self.pq.num_rows-1))
            else: self.schema_scroll=min(self.schema_scroll+1,max(0,len(self.pq.lines)-1))
        elif key in ('\x1b[A','k'):
            if self.tab==0: self.row=max(0,self.row-1)
            else: self.schema_scroll=max(0,self.schema_scroll-1)
        elif key=='d': self.row=min(self.row+10,max(0,self.pq.num_rows-1))
        elif key=='u': self.row=max(0,self.row-10)
        return True

def read_key(timeout=0.5):
    r,_,_=select.select([sys.stdin],[],[],timeout)
    if not r: return ''
    ch=sys.stdin.read(1)
    if ch=='\x1b':
        # gather a short escape sequence
        while select.select([sys.stdin],[],[],0.01)[0]:
            ch += sys.stdin.read(1)
            if len(ch)>8: break
    return ch

# ---- CLI / terminal lifecycle ----
def parse_args(argv):
    if any(a in ('-h','--help') for a in argv): print(HELP,end=''); return None,0
    if any(a in ('-V','--version') for a in argv): print(VERSION); return None,0
    vals=[]; end=False
    for a in argv:
        if not end and a=='--': end=True; continue
        if not end and a.startswith('--'):
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable <PATH>\n\nFor more information, try '--help'.\n")
            return None,2
        if not end and a.startswith('-') and a!='-':
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: executable <PATH>\n\nFor more information, try '--help'.\n")
            return None,2
        vals.append(a)
    if not vals:
        sys.stderr.write("error: the following required arguments were not provided:\n  <PATH>\n\nUsage: executable <PATH>\n\nFor more information, try '--help'.\n")
        return None,2
    if len(vals)>1:
        sys.stderr.write(f"error: unexpected argument '{vals[1]}' found\n\nUsage: executable <PATH>\n\nFor more information, try '--help'.\n")
        return None,2
    return vals[0],None

def non_tty_panic():
    sys.stdout.write('\x1b[?1049l'); sys.stdout.flush()
    sys.stderr.write("\nthread 'main' (1) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/ratatui-0.29.0/src/terminal/init.rs:52:16:\nfailed to initialize terminal: Os { code: 6, kind: Uncategorized, message: \"No such device or address\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    return 101

def main(argv):
    path,code=parse_args(argv)
    if code is not None: return code
    if not sys.stdout.isatty() or not sys.stdin.isatty():
        return non_tty_panic()
    sys.stdout.write('\x1b[?1049h'); sys.stdout.flush()
    try:
        pq=ParquetFile(path)
        # Force initial decode so page errors are displayed like the original before drawing.
        pq.values()
    except RuntimeError as e:
        sys.stdout.write(f"Error: Custom {{ kind: Other, error: \"{str(e)}\" }}")
        sys.stdout.flush(); return 1
    old=None
    try:
        old=termios.tcgetattr(sys.stdin.fileno()); tty.setcbreak(sys.stdin.fileno())
        app=App(pq); app.draw()
        while True:
            k=read_key(0.25)
            if k:
                if not app.handle(k): break
                app.draw()
    finally:
        if old is not None:
            try: termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, old)
            except Exception: pass
        sys.stdout.write('\x1b[?1049l\x1b[?25h'); sys.stdout.flush()
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
