            name = 'root' if depth==0 else get_name(se)
            line = '└─ root' if depth==0 else prefix + ('└─ ' if is_last else '├─ ') + name
            self.lines.append((line, se, list(path)+([] if depth==0 else [name])))
            n=se.get(5,0) or 0
            if n:
                if depth==0:
                    child_prefix = '   '
                    child_path = []
                else:
                    child_prefix = prefix + ('   ' if is_last else '│  ')
                    child_path = path + [name]
                for j in range(n): rec(child_path, child_prefix, j==n-1, depth+1)
            else:
                if depth>0: self.leaves.append((path+[name], se))
        rec([], '', True, 0)
